def find_kth(arr1, arr2, k):
    """
    Finds the k-th element in the merged sorted list of two given sorted arrays.

    :param arr1: First sorted array
    :param arr2: Second sorted array
    :param k: The 1-based index of the element to find in the merged array
    :return: The k-th element in the merged sorted array
    """
    def kth_util(a, b, k):
        # If one array is empty, return the k-th element from the other array
        if not a:
            return b[k - 1]
        if not b:
            return a[k - 1]

        # If k == 1, return the smallest element
        if k == 1:
            return min(a[0], b[0])

        # Divide k into two parts
        idx_a = min(k // 2, len(a))
        idx_b = k - idx_a
        val_a = a[idx_a - 1]
        val_b = b[idx_b - 1]

        # Compare and reduce the search space
        if val_a <= val_b:
            return kth_util(a[idx_a:], b, k - idx_a)
        else:
            return kth_util(a, b[idx_b:], k - idx_b)

    return kth_util(arr1, arr2, k)

# Example usage and test
assert find_kth([2, 3, 6, 7, 9], [1, 4, 8, 10], 5) == 6
```

