def move_num(s):
    letters, numbers = [], []

    for char in s:
        if char.isdigit():
            numbers.append(char)
        else:
            letters.append(char)

    return ''.join(letters) + ''.join(numbers)

# Test cases
assert move_num('I1love143you55three3000thousand') == 'Iloveyouthreethousand1143553000'
assert move_num('abc123') == 'abc123'
assert move_num('123abc') == 'abc123'
assert move_num('noDigitsHere') == 'noDigitsHere'
assert move_num('') == ''
```

